import io, re
base = r'bench/data/'
o = io.open(base + 'long-article.md', encoding='utf-8').read()
t = io.open(base + 'long-article-summary-200.md', encoding='utf-8').read().split('\n', 2)[2].strip()

def norm(s):
    return re.sub(r'[^\w\u4e00-\u9fff]', '', s)

o, t = norm(o), norm(t)
best = ''
for i in range(len(t)):
    for j in range(i + len(best) + 1, len(t) + 1):
        if t[i:j] in o:
            best = t[i:j]
        else:
            break
print('summary_chars', len(t))
print('longest_common_substr', repr(best), len(best))
print('over_10_chars', len(best) > 10)
